// ด่านตรวจเลขที่เรื่อง: เลข BS- ทุกตัวในคำตอบต้องมีอยู่จริงในตาราง citizen_requests
const output = String($json.output ?? '');
const tickets = [...new Set(output.match(/BS-\d+/g) ?? [])];
return { json: { output, tickets: JSON.stringify(tickets) } };

// ด่านสุดท้ายก่อนถึงประชาชน: คำตอบว่าง หรืออ้างเลขที่ที่ไม่มีอยู่จริง ไม่ส่งออกไป
const output = $('เลขที่ในคำตอบ').first().json.output;
const missing = $json.missing ?? [];
if (!output.trim()) {
  // พบเมื่อโมเดลสำรองตอบกลับเป็นข้อความว่าง
  return { json: { output: 'ขออภัยค่ะ ตอนนี้ระบบตอบคำถามนี้ไม่ได้ กรุณาโทร 0 4400 1234 ในเวลาราชการค่ะ', blocked: 'empty' } };
}
if (missing.length > 0) {
  return { json: { output: 'ขออภัยค่ะ ระบบยังบันทึกเรื่องนี้ไม่สำเร็จ กรุณาแจ้งอีกครั้งพร้อมสถานที่ หรือโทรสายด่วน 0 4400 1299 ได้ตลอด 24 ชั่วโมงค่ะ', blocked: missing } };
}
return { json: { output } };
